code='''def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    # Vertical 5 dividers extend a horizontal color tile along the divider.
    for c in range(w):
        rows=[r for r in range(h) if grid[r][c]==5]
        if len(rows)<2: continue
        lo,hi=min(rows),max(rows)
        colored=[r for r in range(lo,hi+1) if c+1<w and any(grid[r][j] not in (0,5) for j in range(c+1,w))]
        if colored:
            end=max(colored)
            start=end
            while start>lo and c+1<w and any(grid[start-1][j] not in (0,5) for j in range(c+1,w)): start-=1
            tile=[[grid[r][j] for j in range(c+1,w)] for r in range(start,end+1)]
            for r in range(lo,hi+1):
                for j in range(c+1,w): out[r][j]=tile[(r-start)%len(tile)][j-c-1]
    # Horizontal dividers extend each adjacent column cue across the 5 segment.
    for r in range(h):
        cols=[c for c in range(w) if grid[r][c]==5]
        if len(cols)<2: continue
        lo,hi=min(cols),max(cols)
        for c in range(lo,hi+1):
            cue=next((i for i in range(r+1,h) if grid[i][c] not in (0,5)),None)
            if cue is not None:
                for i in range(r+1,h):
                    if grid[i][c] not in (0,5): out[i][c]=grid[i][c]
                # Fill the row from the cue, only where the region was blank.
                for i in range(r+1,h):
                    if grid[i][c] not in (0,5):
                        for j in range(lo,hi+1): out[i][j]=grid[i][c]
    return out
'''
